INSERT INTO feature VALUES('unit-readings','workflow','Readings considered on every axis',NULL,'implemented','ordinary',NULL,'Every unit answers the eight reading axes with its reason, the seventh, `zero-cost`, asking what the change adds at run time and what demands it, and the eighth, `nominal`, what names, freshness, support and renaming give it and its behaviour as a nominal automaton over allocations, uses and releases. `unit:check` refuses an issue''s row that is not `yes — <what it gives>` or `no — <why it does not reach it>`; `pr:open` refuses a pull request''s row that is not `answered:`, `trivial:`, `not applicable:` with its clause or `deferred: #n`, and a selected axis answered otherwise without a `departed:` source; `claim:next` claims a unit whose readings hold the migration''s `unstated` placeholder and prints their questions first, and `pr:open` refuses its landing until the seat has restated them on the issue. Each refusal quotes the axis''s question, and the issue and pull request templates carry it.',NULL,'.config/bodies/unit.json .config/bodies/opening.json .config/claims/next.json',NULL,NULL);
